import re,glob,os
tbl={}
for line in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|',line)
    if m: tbl[int(m.group(1))]=m.group(2)
print(len(tbl), sorted(tbl))
used={}
for f in sorted(glob.glob('draft/0*.md'))+sorted(glob.glob('figures/*.md')):
    txt=open(f).read()
    nums=set(int(n) for n in re.findall(r'(?<![\d.])\b(\d{2})\b(?!\.)',txt))
    used[f]=nums
allused=set()
for f,n in used.items():
    print(f, sorted(n))
    allused|=n
print("in text not in table:", sorted(allused-set(tbl)))
print("in table not in text:", sorted(set(tbl)-allused))
EOF

